<?php require_once __DIR__.'/config/security.php'; require_permission('floorplan.view'); $page_title='Campus Floor Plan'; $rooms=$pdo->query("SELECT * FROM floorplan_rooms ORDER BY id")->fetchAll(); $dev=$pdo->query("SELECT id,device_name,status,location FROM devices ORDER BY device_name")->fetchAll(); include __DIR__.'/partials/header.php'; ?>
<div class="hero compact"><div><div class="eyebrow">CAMPUS VISUALIZATION</div><h1>Interactive campus floor plan</h1><p>Room-level view of network infrastructure. Device status is shown by color.</p></div></div>
<div class="panel"><div class="floorplan" id="floorplan"><?php foreach($rooms as $r): $matched=array_values(array_filter($dev,fn($d)=>stripos($d['location']??'',$r['room_name'])!==false || stripos($r['room_name'],$d['location']??'')!==false)); ?><div class="room" style="left:<?=$r['x_pos']?>%;top:<?=$r['y_pos']?>%;width:<?=$r['width']?>%;height:<?=$r['height']?>%" onclick="roomInfo('<?=e($r['room_name'])?>',<?=htmlspecialchars(json_encode($matched),ENT_QUOTES,'UTF-8')?>)"><b><?=e($r['room_name'])?></b><small><?=e($r['building'])?></small><?php foreach($matched as $d):?><i class="device-pin <?=strtolower($d['status'])?>" title="<?=e($d['device_name'])?>"></i><?php endforeach;?></div><?php endforeach;?></div></div>
<div class="modal" id="roomModal"><div class="modal-card"><div class="modal-head"><h3 id="roomTitle">Room</h3><button class="close" onclick="q('#roomModal').classList.remove('show')">×</button></div><div id="roomBody" class="ticket-detail"></div></div></div><script>function roomInfo(n,d){q('#roomTitle').textContent=n;q('#roomBody').innerHTML=d.length?d.map(x=>'<p><b>'+x.device_name+'</b><br>'+x.status+' · '+x.location+'</p>').join(''):'<p class="muted">No linked devices yet. Assign device locations to this room.</p>';q('#roomModal').classList.add('show')}</script>
<?php include __DIR__.'/partials/footer.php'; ?>
